architecture.h4_f:
|
msg = CBOR{v:1, টেক্সট, reply_to, send_at}
ct = AES-GCM-256-এনক্রিপ্ট(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
|
pt = CBOR{v:1, text, reply_to?, thread_id?, উল্লেখ?, sent_at}
ct = AES-GCM-256-এনক্রিপ্ট(room_key, nonce, pt, aad=hex(room_id))
তার = CBOR{
  v: 1,
  সাইফারটেক্সট: হেক্স(ct), // পরিবর্তনশীল দৈর্ঘ্য
  ননস: হেক্স (12 বি),
  sender_pseudo: hex(16 B),
  send_at: unix_ms
}

cryptoWire.h5_f:
|
বাইরের = CBOR{
  source_node: hex32,
  লক্ষ্য_ব্যবহারকারী: int64,
  inner_ciphertext: বাইট,
  inner_nonce: বাইট,
  send_at: unix_ms
}
sig = Ed25519-সাইন (সোর্স_প্রিভি, বাইরের)
POST /ফেডারেশন/ডেলিভার { খাম: বাইরের, সাইগ: হেক্স৬৪ }

auth.h1_f:
|
POST /api/অথেন্টিকেশন/রেজিস্টার
  { ব্যবহারকারীর নাম, পাসওয়ার্ড, x25519_public_key, display_name, phone?, email?, avatar_emoji }

প্রতিক্রিয়া 201 তৈরি করা হয়েছে:
  { অ্যাক্সেস_টোকেন, রিফ্রেশ_টোকেন, ব্যবহারকারী_আইডি, ব্যবহারকারীর নাম, ... }

auth.h3_f:
অ্যাক্সেস_টোকেন পেলোড:
  { উপ: user_id, jti: device_id, টাইপ: "অ্যাক্সেস", মেয়াদ: এখন + 15 মিনিট }
refresh_token পেলোড:
  { উপ: user_id, jti: device_id, টাইপ: "রিফ্রেশ", exp: now + 30d }

.env থেকে নোডের 64-বাইট সিক্রেট সহ HS256-স্বাক্ষরিত

auth.h7_f:
|
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR পেলোড = { nonce, user_id, সার্ভার: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → নতুন ডিভাইস নিবন্ধিত; JWTs ফিরে এসেছে।

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 হেক্স
সাইফারটেক্সট = AES-GCM-এনক্রিপ্ট(room_key, nonce, CBOR_payload, aad=room_id)

ফ্যান-আউট ফ্রেম: { type:"m", রুম, বার্তা:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
|
init POST /api/files/resumable/init {ফাইলের নাম, আকার, chunk_size_hint}
            ← {upload_id, chunk_size}
খণ্ড PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← ২০৪
চূড়ান্ত করুন POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL অসমাপ্ত: 24 ঘন্টা

calls.h1_f:
|
POST /api/calls/{room_id}/start {ভিডিও, অডিও} → call_id
WS সম্প্রচার {type:"c", kind:"invite", call_id}
WS সম্প্রচার {টাইপ:"c", ধরনের:"অফার", sdp}
WS সম্প্রচার {টাইপ:"c", ধরনের:"উত্তর", sdp}
WS সম্প্রচার {টাইপ:"c", প্রকার:"প্রার্থী", ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
খাম = {
  source_node : hex32,
  লক্ষ্য_ব্যবহারকারী: int64,
  inner_ciphertext: বাইট,
  inner_nonce : বাইট,
  send_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(খাম))
POST /ফেডারেশন/ডেলিভার { খাম, স্বাক্ষর }

push.h4_f:
|
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
ওয়েব SW: self.addEventListener('push', e => ডিক্রিপ্ট(e.data))

controller.h2_f:
|
টুল = সাইন_টুল
ইনপুট = উৎস গাছ, কী/release.key
প্রকাশ = {
  সংস্করণ: "0.1.0",
  বিল্ট_এট: ইউনিক্স_এমএস,
  ফাইল: [{পথ, sha256, আকার}, ...]
}
sig = Ed25519-সাইন(রিলিজ_প্রিভ, CBOR(প্রকাশিত))
আউটপুট = INTEGRITY.sig.json = {manifest, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
|
তৈরি করুন: POST /api/bots {ব্যবহারকারীর নাম, প্রদর্শন_নাম, কোড}
          → {bot_id, টোকেন, pubkey}
রান: ইন-প্রসেস (নোডের ভিতরে কোরোটিন)
      OR বাহ্যিক (লং-পোল /api/bots/{id}/updates, টোকেন-প্রমাণকৃত)
বার্তা: {পাঠ্য, স্বাক্ষর: Ed25519-সাইন(bot_priv, canonical_msg)}

bots.h2_f:
|
অন /শুরু {
  "স্বাগতম, {ctx.first_name}" নির্গত করুন
}
এ/অ্যাড <আইটেম> {
  state.list = (state.list বা []) + [ctx.args.item]
  নির্গত করা "যোগ করা হয়েছে: {ctx.args.item}"
}

security.h4_f:
|
canary.txt (প্রতিদিন):
  {তারিখ, স্বাক্ষর: Ed25519-সাইন(release_priv, date)}
ক্লায়েন্ট যাচাই করে → অনুপস্থিত বা অবৈধ ⇒ আপস সন্দেহজনক

জরুরী:
  অ্যাডমিন POST /api/admin/revoke-all {reason}
  নোড ব্রডকাস্ট {টাইপ:"এন", ইভেন্ট:"আপস", কারণ}
  ক্লায়েন্ট কীগুলি মুছে দেয়, পুনরায় বুটস্ট্র্যাপ জোর করে

debugging.h2_f:
|
হার হিস্টোগ্রাম (প্রতি রুট + পদ্ধতি):
  vortex_http_requests_total{রুট,পদ্ধতি,স্থিতি}
  vortex_http_request_duration_seconds_backet{রুট,পদ্ধতি,le}

ওয়েবসকেট গেজ:
  vortex_ws_connections{নোড}
  vortex_ws_fanout_queue_depth{room,user}

কাস্টম কাউন্টার:
  ঘূর্ণি_বার্তা_প্রেরিত_মোট{রুম_টাইপ}
  vortex_calls_started_total{kind}

